 static Bitmap LoadMapBitmap(string path){
  // GDI+ filename loading rejects the extended prefix emitted by Python.
  // Decode via a stream, then detach the bitmap before releasing the stream.
  using(var stream=File.OpenRead(path))
  using(var decoded=new Bitmap(stream)){return new Bitmap(decoded);}
 }
 static string PythonRuntime(){string p=Path.Combine(Root,"runtime","python.exe");return File.Exists(p)?p:@"D:\comfy\ComfyUI_windows_portable\python_embeded\python.exe";}
 static string RunPython(string script,string arguments){
  var si=new ProcessStartInfo(PythonRuntime(),"-X utf8 "+Quote(Path.Combine(Root,script))+" "+arguments){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Root,RedirectStandardError=true,RedirectStandardOutput=true,StandardErrorEncoding=Encoding.UTF8,StandardOutputEncoding=Encoding.UTF8};
  using(var p=Process.Start(si)){var error=p.StandardError.ReadToEndAsync();string output=p.StandardOutput.ReadToEnd();p.WaitForExit();if(p.ExitCode!=0)throw new Exception(error.Result);return output;}
 }
