 static int WrappedFlowHeight(FlowLayoutPanel panel,int width){
  int available=Math.Max(1,width-panel.Padding.Horizontal),x=0,row=0,total=panel.Padding.Vertical;
  foreach(Control c in panel.Controls){
   Size preferred=c.AutoSize?c.GetPreferredSize(new Size(available,0)):c.Size;
   int w=preferred.Width+c.Margin.Horizontal,h=preferred.Height+c.Margin.Vertical;
   if(x>0&&x+w>available){total+=row;x=0;row=0;}
   x+=w;row=Math.Max(row,h);
  }
  return total+row;
 }
