 TerrainData LoadTerrain(int template){lock(terrainCache){TerrainData data;if(terrainCache.TryGetValue(template,out data))return data;string path=Path.Combine(Root,"terrain-template-"+template+".json");if(!File.Exists(path)){var info=Json.Deserialize<Dictionary<string,string>>(RunPython("creator_terrain.py",template.ToString()));path=info["metadata"];}data=Json.Deserialize<TerrainData>(File.ReadAllText(path,Encoding.UTF8));terrainCache[template]=data;return data;}}

 void BuildGovernanceTab(){
  var tab=new TabPage("5  통치자·황제 지지도"){BackColor=Paper};tabs.TabPages.Add(tab);
  var panel=new TableLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,ColumnCount=2,RowCount=9,Padding=new Padding(22)};
