  var note=new Label{Dock=DockStyle.Fill,AutoSize=false,ForeColor=Dark};
  string[] labels={"","설정 사용","통치자 직급","초기 봉급","개인 재산 (데나리)","초기 황제 지지도","지지도 운영 방식"};
  /* the city is the one chosen at the top (user 2026-11-15): hidden picker, the name as heading */var governanceHeading=new Label{AutoSize=true,Font=new Font("Malgun Gothic",13,FontStyle.Bold),Padding=new Padding(0,4,0,0)};var governanceHead=new FlowLayoutPanel{AutoSize=true,WrapContents=false};city.Visible=false;governanceHead.Controls.Add(city);governanceHead.Controls.Add(governanceHeading);
  Control[] fields={governanceHead,use,rank,salary,savings,favor,policy};
  panel.Controls.Add(governanceHead,0,0);panel.SetColumnSpan(governanceHead,2);   /* the heading starts at the left edge */for(int i=1;i<fields.Length;i++){panel.Controls.Add(new Label{Text=labels[i],AutoSize=true,Padding=new Padding(0,6,0,0)},0,i);panel.Controls.Add(fields[i],1,i);}
  panel.Controls.Add(note,0,7);panel.SetColumnSpan(note,2);panel.SetRowSpan(note,2);
  bool binding=false;
  Action refreshNote=()=>{foreach(var c in new Control[]{rank,salary,savings,favor,policy})c.Enabled=use.Checked;if(ThroneEnabled)policy.Enabled=false;   // the struggle for the throne needs the original favour rules (ThroneGovernance)
   // Amounts from the engine check of this slot's map (CreatorSalary.cs). Relabelling never changes a saved value.
   var facts=city.SelectedIndex<0?null:SalaryFor(city.SelectedIndex);bool was=binding;binding=true;try{LabelSalaryLists(rank,salary,facts);}finally{binding=was;}
   note.Text=!use.Checked?"기존 시나리오의 시작 방식을 유지합니다. 현재 멀티 초기화는 시민 직급·지지도 50이며 원본 증감 규칙을 따릅니다.":
    (policy.SelectedIndex==0?"지지도를 지정한 값으로 유지합니다. 봉급·공물·황제 선물로도 바뀌지 않습니다. 봉급 지급 자체는 그대로입니다.":"직급에 맞는 봉급도 연간 기본 지지도 감소를 막지는 않습니다. 공물 미납 등 원본 규칙도 적용됩니다.")+
    ((salary.SelectedIndex-1>rank.SelectedIndex && policy.SelectedIndex==1)?"\n주의: 봉급이 직급보다 높아 지지도가 추가로 감소할 수 있습니다.":"");
   note.Text+="\n"+SalaryNote(use.Checked,Math.Max(0,rank.SelectedIndex),salary.SelectedIndex-1,facts);
   if(ThroneEnabled&&use.Checked)note.Text+="\n황위 쟁탈전에서는 원본 황제 호감도 규칙이 작동해야 하므로 지지도 운영 방식은 원본 규칙으로 고정됩니다.";
   note.Text+="\n새 게임을 시작할 때 적용합니다. 기존 이어하기 저장본은 바꾸지 않습니다. 도시 운영 자금과 개인 재산은 별개입니다.";
  };
  Action load=()=>{if(project==null||city.SelectedIndex<0)return;governanceHeading.Text=CityName(project.slots[city.SelectedIndex].name_id)+Lang.T("의 통치자와 황제 지지도");binding=true;var g=project.slots[city.SelectedIndex].governance;use.Checked=g!=null;g=g??new Governance();rank.SelectedIndex=g.rank;salary.SelectedIndex=g.salary_rank+1;savings.Value=g.savings;favor.Value=g.favor;policy.SelectedIndex=g.policy=="fixed"&&!ThroneEnabled?0:1;binding=false;refreshNote();};
  Action save=()=>{if(binding||project==null||city.SelectedIndex<0)return;project.slots[city.SelectedIndex].governance=use.Checked?new Governance{rank=rank.SelectedIndex,salary_rank=salary.SelectedIndex-1,savings=(int)savings.Value,favor=(int)favor.Value,policy=policy.SelectedIndex==0&&!ThroneEnabled?"fixed":"original"}:null;refreshNote();Changed();};
  tab.Enter+=(sender,e)=>{binding=true;int old=city.SelectedIndex;city.Items.Clear();if(project!=null)foreach(var slot in project.slots)city.Items.Add(slot.id+" / "+CityName(slot.name_id));city.SelectedIndex=city.Items.Count==0?-1:Math.Max(0,Math.Min(old,city.Items.Count-1));binding=false;load();};
  city.SelectedIndexChanged+=(sender,e)=>{if(!binding)load();};use.CheckedChanged+=(sender,e)=>save();rank.SelectedIndexChanged+=(sender,e)=>save();salary.SelectedIndexChanged+=(sender,e)=>save();savings.ValueChanged+=(sender,e)=>save();favor.ValueChanged+=(sender,e)=>save();policy.SelectedIndexChanged+=(sender,e)=>save();
 }

 void BuildConstructionTab(){
  var tab=new TabPage("2  도시 지형·건설 허용"){BackColor=Paper};tabs.TabPages.Add(tab);
  var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=4,Padding=new Padding(14)};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,180));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,44));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,72));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,42));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));tab.Controls.Add(layout);
  var select=new FlowLayoutPanel{Dock=DockStyle.Fill};/* the terrain is chosen on the 지형 page (user 2026-11-15); here only what the city uses, in words */slotPicker.Visible=false;select.Controls.Add(slotPicker);terrainNow.Font=new Font("Malgun Gothic",13,FontStyle.Bold);terrainNow.Padding=new Padding(0,4,0,0);select.Controls.Add(terrainNow);layout.Controls.Add(select,0,0);layout.SetColumnSpan(select,2);
  
  buildingHelp.Text="새 시나리오는 모든 건물을 허용합니다. 기존 시나리오의 제한은 그대로 유지됩니다. 분류를 고르고 도시별로 허용할 건물을 체크하세요.\n체크는 해당 도시에만 적용됩니다. 자원·지형 조건은 게임 규칙을 따릅니다.";layout.Controls.Add(buildingHelp,0,1);layout.SetColumnSpan(buildingHelp,2);
  var tools=new FlowLayoutPanel{Dock=DockStyle.Fill};tools.Controls.Add(new Label{Text="건물 찾기",AutoSize=true,Padding=new Padding(0,6,0,0)});tools.Controls.Add(buildingSearch);tools.Controls.Add(Button("표시된 건물 모두 허용",()=>SetVisible(true)));tools.Controls.Add(Button("표시된 건물 모두 제한",()=>SetVisible(false)));tools.Controls.Add(Button("다른 도시에 동일 적용",CopyBuildings));tools.Controls.Add(Button("이 도시 모든 건물 허용",()=>{if(slotPicker.SelectedIndex<0)return;project.slots[slotPicker.SelectedIndex].allowed_buildings=catalog.Select(b=>b.id).ToArray();RefreshBuildings();Changed();}));layout.Controls.Add(tools,0,2);layout.SetColumnSpan(tools,2);layout.Controls.Add(categories,0,3);/* tiles with the game's pictures (CreatorBuildingTiles.cs); the checked list keeps the choice, hidden */layout.Controls.Add(buildingTiles,1,3);buildings.Visible=false;tab.Controls.Add(buildings);tab.Enter+=(s,e)=>LoadBuildingPictures();tab.VisibleChanged+=(s,e)=>{if(tab.Visible)LoadBuildingPictures();};
  var names=new List<string>{"전체 건물"};names.AddRange(catalog.Select(b=>b.category).Distinct());foreach(string n in names){string keep=n;var cb=Button(n,()=>{category=keep=="전체 건물"?"":keep;RefreshBuildings();},155);cb.Tag=n;categories.Controls.Add(cb);}
  slotPicker.SelectedIndexChanged+=(s,e)=>{if(!loading)ShowSlot();};terrain.SelectedIndexChanged+=(s,e)=>{if(!loading && slotPicker.SelectedIndex>=0 && terrain.SelectedItem!=null){var current=project.slots[slotPicker.SelectedIndex];if(ApplyTerrainVersion(current,((TerrainChoice)terrain.SelectedItem).id,slotFiles))UpdateBuildingHelp(current);else ShowSlot();}};
  buildingSearch.TextChanged+=(s,e)=>RefreshBuildings();buildings.ItemCheck+=(s,e)=>{if(loading||slotPicker.SelectedIndex<0)return;var slot=project.slots[slotPicker.SelectedIndex];var ids=new HashSet<int>(slot.allowed_buildings);int id=((BuildingChoice)buildings.Items[e.Index]).id;if(e.NewValue==CheckState.Checked&&SeaBlocked(slot.id,id)){e.NewValue=e.CurrentValue;status.Text=CityName(slot.name_id)+": 해상 교역 불가 — "+SeaLimit(slot.id).reason+" 이 건물은 선택할 수 없습니다.";return;}if(e.NewValue==CheckState.Checked)ids.Add(id);else ids.Remove(id);slot.allowed_buildings=ids.OrderBy(x=>x).ToArray();Changed();};buildings.ItemCheck+=(s,e)=>BuildingTileChecked(e);   /* after the rule above, which may refuse */
 }
 void RefreshBuildings(){if(project==null || slotPicker.SelectedIndex<0)return;loading=true;buildings.Items.Clear();var slot=project.slots[slotPicker.SelectedIndex];var seaLimit=SeaLimit(slot.id);string find=buildingSearch.Text.Trim();foreach(var b in catalog.Where(b=>(category=="" || b.category==category) && (find.Length==0 || b.name.IndexOf(find,StringComparison.CurrentCultureIgnoreCase)>=0)))buildings.Items.Add(SeaBuildingBlocked(seaLimit,b.id)?new BuildingChoice{id=b.id,name=b.name+" (해상 교역 불가)",category=b.category}:b,Array.IndexOf(slot.allowed_buildings,b.id)>=0);loading=false;ShowBuildingTiles();status.Text=CityName(slot.name_id)+": "+slot.allowed_buildings.Length+"개 건물 허용 / 목록 "+buildings.Items.Count+"개"+SeaNote(slot.id);foreach(Button b in categories.Controls)b.BackColor=((string)b.Tag==category || (category=="" && (string)b.Tag=="전체 건물"))?Color.FromArgb(174,143,98):ButtonFace;}
 List<MapVersion> slotFiles=new List<MapVersion>();Label terrainNow=new Label{AutoSize=true,Padding=new Padding(0,8,12,0)};
 void ShowSlot(){if(project==null || slotPicker.SelectedIndex<0)return;loading=true;var slot=project.slots[slotPicker.SelectedIndex];terrain.Items.Clear();int current;var choices=TerrainVersions(slot,out slotFiles,out current);foreach(var item in choices)terrain.Items.Add(new TerrainChoice{id=item.id,name=(item.id<0||item.name_id==slot.name_id?"":"기존 배정 · ")+item});for(int i=0;i<terrain.Items.Count;i++)if(((TerrainChoice)terrain.Items[i]).id==current)terrain.SelectedIndex=i;terrainNow.Text=CityName(slot.name_id)+Lang.T("의 건설 허용");loading=false;UpdateBuildingHelp(slot);RefreshBuildings();}
 void UpdateBuildingHelp(Slot slot){buildingHelp.Text="새 시나리오는 모든 건물을 허용합니다. 기존 시나리오의 제한은 그대로 유지됩니다. 분류를 고르고 도시별로 허용할 건물을 체크하세요.\n체크는 해당 도시에만 적용됩니다. 자원·지형 조건은 게임 규칙을 따릅니다.";var preset=Array.Find(presets.terrain,p=>p.id==slot.campaign_scenario);if(preset!=null&&preset.original_population>0)buildingHelp.Text+="\n"+preset.PopulationNotice;}
 // All shown at once (user 2026-11-15: one by one through the list's check event took ages with the tiles): one new
 // list, one refresh, one change. The sea rule of the check event applies the same way.
 void SetVisible(bool enabled){if(project==null||slotPicker.SelectedIndex<0)return;var slot=project.slots[slotPicker.SelectedIndex];var ids=new HashSet<int>(slot.allowed_buildings);int refused=0;
  foreach(var item in buildings.Items.Cast<BuildingChoice>()){if(!enabled)ids.Remove(item.id);else if(SeaBlocked(slot.id,item.id)){if(!ids.Contains(item.id))refused++;}else ids.Add(item.id);}
  slot.allowed_buildings=ids.OrderBy(x=>x).ToArray();RefreshBuildings();Changed();
  if(refused>0)status.Text=CityName(slot.name_id)+": "+Lang.T("해상 교역 불가로 허용하지 않은 건물")+" "+refused+Lang.T("개")+" "+SeaNote(slot.id);}
 void CopyBuildings(){if(slotPicker.SelectedIndex<0)return;if(LangBox.Show(this,"선택한 도시의 건설 허용 목록을 나머지 플레이어 도시에 복사할까요?","건설 목록 복사",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;var current=project.slots[slotPicker.SelectedIndex];foreach(var s in project.slots)s.allowed_buildings=(int[])current.allowed_buildings.Clone();Changed();}
 void UpdatePosition(){if(loading || selected<0)return;map.MoveCity(project.empire.cities[selected].name_id,(int)posX.Value,(int)posY.Value);}
 void RefreshCityList(){SearchCityList();}
 void RefreshCities(){loading=true;int chosen=selected>=0?project.empire.cities[selected].name_id:0;project.empire.cities=project.empire.cities.OrderBy(c=>c.role=="player"?Array.FindIndex(project.slots,p=>p.name_id==c.name_id):100+c.name_id).ToArray();selected=Array.FindIndex(project.empire.cities,c=>c.name_id==chosen);RefreshCityList();slotPicker.Items.Clear();for(int i=0;i<project.slots.Length;i++)slotPicker.Items.Add("P"+(i+1)+"  "+CityName(project.slots[i].name_id));if(slotPicker.Items.Count>0)slotPicker.SelectedIndex=0;terrainSlot.Items.Clear();for(int i=0;i<project.slots.Length;i++)terrainSlot.Items.Add("P"+(i+1)+"  "+CityName(project.slots[i].name_id));if(terrainSlot.Items.Count>0)terrainSlot.SelectedIndex=0;boundTerrainSlot=-1;loading=false;ShowSlot();RefreshObjectives();RefreshMapCards();RefreshEventCities();RefreshInvasionCities();}
 void Upgrade(Scenario data){AdoptThrone(data);/* format 5 = format 4 + rules.throne and Rome (CreatorThrone.cs) */if(data.rules!=null)data.rules["player_transport"]="land";/* players always trade overland (older files could say sea) */if(data.schema==1){LoadEmpireMap(data.empire.template);foreach(var c in data.empire.cities){var at=Array.Find(map.Data.cities,x=>x.name_id==c.name_id);c.x=at==null?1000:at.x;c.y=at==null?500:at.y;}foreach(var s in data.slots)s.allowed_buildings=catalog.Select(b=>b.id).ToArray();}if(data.schema<3){data.schema=3;data.rules["starting_funds"]=10000;foreach(var c in data.empire.cities)c.enabled=true;}data.schema=4;MergeMissingCities(data);}
 void Adopt(Scenario data,bool goalsChosen=true){objectiveChosen=goalsChosen;try{AdoptInner(data,goalsChosen);try{ShelfTakeFrom(project);int based=SafeBases(project);if(based>0){Changed();status.Text=Lang.T("자기 지도를 쓰는 도시의 시작 미션을 모든 시저 3에 있는 캠페인 미션으로 바꿨습니다. 저장해 주세요.")+" ("+based+")";}}catch{}}finally{SyncPlayable();}}
 // 시작 연도 (user 2026-11-17): rules.start_year, BC negative, -500..300 without 0; -350 (the game's usual year) is not written.
 ComboBox startEra=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=72};NumericUpDown startYear=new NumericUpDown{Minimum=1,Maximum=500,Value=350,Width=60};
 void ShowStartYear(Scenario data){object v;int year=data.rules.TryGetValue("start_year",out v)&&v!=null?Convert.ToInt32(v):-350;if(year==0||year<-500||year>300)year=-350;startEra.SelectedIndex=year<0?0:1;startYear.Maximum=year<0?500:300;startYear.Value=Math.Abs(year);}
 void StartYearChanged(){if(startEra.SelectedIndex<0)return;int most=startEra.SelectedIndex==0?500:300;if(startYear.Value>most)startYear.Value=most;startYear.Maximum=most;if(loading||project==null)return;int year=startEra.SelectedIndex==0?-(int)startYear.Value:(int)startYear.Value;object v;int had=project.rules.TryGetValue("start_year",out v)&&v!=null?Convert.ToInt32(v):-350;if(year==had)return;if(year==-350)project.rules.Remove("start_year");else project.rules["start_year"]=year;Changed();}
 void AdoptInner(Scenario data,bool goalsChosen){if(data.slots.Length>8)throw new Exception("제작기는 최대 8개 플레이어 도시를 지원합니다. 원본 파일은 변경하지 않았습니다.");assignmentSlot=-1;editPositions.Checked=false;citySearch.Text="";map.FitMap();objectivesInitialized=false;nativeSessions.Clear();nativePreviews.Clear();cityNotes.Clear();LoadEmpireMap(data.empire.template);foreach(var slot in data.slots)if(slot.terrain_edits==null)slot.terrain_edits=new TerrainEdit[0];loading=true;project=data;selected=-1;title.Text=data.title;briefingText.Text=(data.briefing??"").Replace("\r\n","\n").Replace("\n","\r\n");LoadStartMessage();startingFunds.Value=data.rules.ContainsKey("starting_funds")?Convert.ToDecimal(data.rules["starting_funds"]):10000;ShowStartYear(data);ShowMakerTools();minPlayers.Minimum=1;minPlayers.Value=data.rules.ContainsKey("min_players")?Math.Max(1,Math.Min(6,Convert.ToInt32(data.rules["min_players"]))):1;MinPlayersFloor();map.Project=data;map.Origin=data.slots[0].name_id;map.PlacementMode=false;loading=false;RefreshCities();SelectCity(data.slots[0].name_id);dirty=false;revisionPending=false;posX.Enabled=posY.Enabled=false;RefreshMapCards();status.Text="P자리 선택 후 녹색 도시를 클릭하면 배정됩니다. 지도 확대·이동은 저장 내용을 바꾸지 않습니다.";}
 void NewFour(){currentProjectPath=null;var data=Json.Deserialize<Scenario>(RunPython("creator_presets.py","--default 4"));Upgrade(data);data.id="scenario-"+Guid.NewGuid().ToString("N");data.revision=1;LocalizeTexts(data);int moved=ShelfApplyPlaces(data);Adopt(data,false);if(moved>0)status.Text=Lang.T("이 PC의 지도 보관함에 있는 도시를 지난번에 놓은 위치에 두었습니다")+": "+moved;}
 void ChooseTerrain(){if(slotPicker.SelectedIndex<0)return;var slot=project.slots[slotPicker.SelectedIndex];List<MapVersion> files;int current;var choices=TerrainVersions(slot,out files,out current);
  // the picker keeps its items: a new map is appended, a removed one keeps its place in `files` (ids stay valid)
  Func<MissionPreset> importer=()=>{var v=MapVersionImport(slot.name_id,slot.campaign_scenario);if(v==null)return null;int k=files.FindIndex(f=>MapKey(f.terrain_asset)==MapKey(v.terrain_asset));if(k<0){files.Add(v);k=files.Count-1;}return VersionItem(files[k],k);};
  Func<MissionPreset,bool> remover=p=>{if(LangBox.Show(this,"이 지도를 도시의 지도 목록에서 뺄까요? 이 지도를 쓰는 다른 시나리오 파일은 바뀌지 않습니다.","지도 목록",MessageBoxButtons.YesNo)!=DialogResult.Yes)return false;MapVersionRemove(files[-1-p.id]);return true;};
  using(var dialog=new CreatorPresetPicker(choices,current,id=>LoadVersion(files,id),false,importer,remover,current)){if(Lang.Shown(dialog).ShowDialog(this)==DialogResult.OK&&dialog.SelectedPreset!=null){ApplyTerrainVersion(slot,dialog.SelectedPreset.id,files);}}ShowSlot();}
 void LoadEmpireMap(int template){if(template==loadedEmpireTemplate)return;var cache=PrepareMap(template);var next=LoadMapBitmap(cache.image);if(map.Background!=null)map.Background.Dispose();map.Background=next;map.Data=Json.Deserialize<MapData>(File.ReadAllText(cache.metadata,Encoding.UTF8));foreach(var c in map.Data.cities)c.name=CityName(c.name_id);foreach(var n in cityNames)if(!map.Data.cities.Any(c=>c.name_id==n.name_id)){var names=map.Data.cities.ToList();names.Add(new MapCity{name_id=n.name_id,name=n.name,x=1000,y=500});map.Data.cities=names.ToArray();}loadedEmpireTemplate=template;posX.Maximum=Math.Max(16,map.Data.width-17);posY.Maximum=Math.Max(16,map.Data.height-17);map.Invalidate();}
 void AddPlayer(){if(project.slots.Length>=8)throw new Exception("플레이어 자리는 최대 8개입니다. 8자리 중 최대 "+OnlinePlayerLimit+"명이 골라서 플레이합니다.");StoreCity();int name=cityNames.Select(c=>c.name_id).FirstOrDefault(candidate=>HasTerrain(candidate)&&LocalAvailableTerrain(candidate)&&!project.slots.Any(p=>p.name_id==candidate));if(name==0)throw new Exception("추가할 플레이 지형이 있는 도시가 없습니다.");string id="player"+(project.slots.Length+1);int suffix=project.slots.Length+1;while(project.slots.Any(p=>p.id==id))id="player"+(++suffix);var list=project.slots.ToList();list.Add(new Slot{governance=new Governance(),id=id,name_id=name,campaign_scenario=PreferredTerrain(name),allowed_buildings=catalog.Select(c=>c.id).ToArray(),terrain_edits=new TerrainEdit[0]});project.slots=list.ToArray();var city=Array.Find(project.empire.cities,c=>c.name_id==name);if(city==null){city=new City{name_id=name,x=1000+project.slots.Length*24,y=500,role="player",enabled=true,sells=new Dictionary<string,int>(),buys=new Dictionary<string,int>()};var all=project.empire.cities.ToList();all.Add(city);project.empire.cities=all.ToArray();}ParkNeutralTrade(city);if(city.map!=null){var created=project.slots[project.slots.Length-1];RestoreParked(created,city.map);AdoptKeptSettings(created,city.map);city.map=null;}city.role="player";city.enabled=true;city.sea=city.cost=0;city.sells.Clear();city.buys.Clear();selected=-1;RefreshCities();SelectCity(name);Changed();}
 void RemovePlayer(){
  if(selected<0||project.empire.cities[selected].role!="player")throw new Exception("제거할 플레이어 도시를 먼저 선택하세요.");
