 }

 void SelectCity(int id){StoreCity();int i=Array.FindIndex(project.empire.cities,c=>c.name_id==id);if(i<0)return;ShowCity(i);}
 void ShowCity(int index){if(IsHandleCreated)BeginInvoke((Action)AfterShowCity);loading=true;selected=index;cities.SelectedIndex=visibleCities.IndexOf(project.empire.cities[index].name_id);var c=project.empire.cities[index];bool npc=c.role=="npc";cityEnabled.Checked=c.enabled;cityEnabled.Enabled=npc;PopulateAssignment(c);PopulateTrade(c);cityTitle.Text=CityName(c.name_id)+(npc?(HasTerrain(c.name_id)?" — 플레이 가능":" — 중립도시"):" — 플레이어 도시");cityHelp.Text=npc?(HasTerrain(c.name_id)?"P자리 카드를 선택하면 플레이어 배정 가능.\n중립도시로 쓰려면 아래 교역 품목을 정하세요.":"플레이어가 이 도시에서 사오거나 팔 물품을 정하세요.\n아래 자원 목록에서 구매·판매할 품목과 연간 수량을 정하세요."):"참가자가 직접 운영하는 도시입니다.\n건물 허용 목록과 지형은 3 플레이 자리 설정 탭에서 설정합니다. 플레이어 간 가격은 게임 안에서 정합니다.";if(npc&&HasTerrain(c.name_id)&&!LocalAvailableTerrain(c.name_id)&&c.map==null&&!ShelfHasMap(c.name_id))cityHelp.Text="플레이 지형이 있는 도시이지만 현재 본편 폴더에는 해당 지도 자료가 없습니다. 본편과 공식 지도 파일을 확인해 주세요.";if(npc&&cityNotes.ContainsKey(c.name_id))cityHelp.Text+="\n원본: "+cityNotes[c.name_id];cost.Value=c.cost;posX.Value=Math.Max(16,Math.Min((int)posX.Maximum,c.x));posY.Value=Math.Max(16,Math.Min((int)posY.Maximum,c.y));sea.Text=npc?"해상 교역만 가능":"플레이어 간 운송: 육로 (고정)";sea.Enabled=npc;seaAuto.Visible=npc;seaAuto.Checked=npc&&c.sea_auto;sea.Checked=npc&&c.sea==1;cost.Enabled=grid.Enabled=removeCity.Enabled=npc;construction.Enabled=construction.Visible=!npc;cityTerrainBar.Visible=npc;RefreshCityTerrainBar(c);if(cityPages.Tag==null||(int)cityPages.Tag!=c.name_id){cityPages.Tag=c.name_id;cityPages.SelectedIndex=0;}   /* a newly chosen city opens on its information (user 2026-11-15: not forced to the trade page) */RefreshAccess(c);grid.Rows.Clear();
  if(npc)for(int r=1;r<=21;r++){string key=r.ToString();bool sells=c.sells.ContainsKey(key),buys=c.buys.ContainsKey(key);int row=grid.Rows.Add(Resources[r-1],sells?"이 도시에서 사오기":buys?"이 도시에 팔기":"거래 안 함",sells?c.sells[key]:buys?c.buys[key]:0);grid.Rows[row].Cells[2].ReadOnly=!sells&&!buys;grid.Rows[row].Cells[2].Style.BackColor=!sells&&!buys?Stone:Paper;}else map.Origin=c.name_id;map.Selected=c.name_id;map.Invalidate();loading=false;
 }
 void StoreCity(){StoreObjectives(false);if(selected<0 || project.empire.cities[selected].role!="npc")return;grid.EndEdit();var sells=new Dictionary<string,int>();var buys=new Dictionary<string,int>();for(int r=1;r<=21;r++){var row=grid.Rows[r-1];string action=Convert.ToString(row.Cells[1].Value);int amount;if(!int.TryParse(Convert.ToString(row.Cells[2].Value),out amount)||amount<0||amount>10000)throw new Exception(Resources[r-1]+": 연간 거래량은 0~10000 정수입니다.");if(action!="거래 안 함" && amount==0)throw new Exception(Resources[r-1]+": 1포대 이상 입력하거나 거래 안 함을 고르세요.");if(action=="이 도시에서 사오기")sells[r.ToString()]=amount;else if(action=="이 도시에 팔기")buys[r.ToString()]=amount;}var c=project.empire.cities[selected];c.cost=(int)cost.Value;c.sea=sea.Checked?1:0;c.sells=sells;c.buys=buys;}
 void BeginAddNeutral(){StoreCity();var available=cityNames.Where(n=>!project.slots.Any(c=>c.name_id==n.name_id)).ToArray();if(available.Length==0)throw new Exception("더 추가할 수 있는 도시가 없습니다.");using(var dialog=new Form{Text="중립도시 추가",ClientSize=new Size(380,135),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,BackColor=Paper,Font=Font}){var pick=new ComboBox{Left=20,Top=20,Width=335,DropDownStyle=ComboBoxStyle.DropDownList};pick.Items.AddRange(available);pick.SelectedIndex=0;dialog.Controls.Add(pick);var ok=new Button{Text="지도에 놓기",Left=130,Top=70,Width=130,DialogResult=DialogResult.OK};dialog.Controls.Add(ok);dialog.AcceptButton=ok;if(Lang.Shown(dialog).ShowDialog(this)==DialogResult.OK){pendingNeutral=((NameChoice)pick.SelectedItem).name_id;CancelMapAssignment();editPositions.Checked=true;pendingNeutral=((NameChoice)pick.SelectedItem).name_id;map.PlacementMode=true;map.Invalidate();status.Text=CityName(pendingNeutral)+": 지도에서 놓을 위치를 클릭하세요. Esc를 누르면 취소합니다.";}}}
 void AddNeutral(int id,int x,int y){if(id<=0)return;if(RomeCapital.TooClose(x,y))throw new Exception(RomeCapital.Refusal);StoreCity();var existing=Array.Find(project.empire.cities,c=>c.name_id==id);if(existing!=null){if(existing.role=="player")throw new Exception("플레이어 도시는 중립도시로 추가할 수 없습니다.");existing.x=x;existing.y=y;existing.enabled=true;}else{if(project.empire.cities.Length>=39)throw new Exception("더 추가할 수 있는 도시가 없습니다.");var list=project.empire.cities.ToList();list.Add(new City{name_id=id,role="npc",enabled=true,x=x,y=y,cost=500,sea=0,sells=new Dictionary<string,int>(),buys=new Dictionary<string,int>()});project.empire.cities=list.ToArray();}pendingNeutral=0;map.PlacementMode=false;selected=-1;RefreshCities();SelectCity(id);Changed();}

 void RemoveNeutral(){if(selected<0 || project.empire.cities[selected].role!="npc")return;cityEnabled.Checked=!cityEnabled.Checked;}

 protected override bool ProcessCmdKey(ref Message msg,Keys keyData){if(keyData==Keys.Escape && assignmentSlot>=0){CancelMapAssignment();return true;}if(keyData==Keys.Escape && map.PlacementMode){pendingNeutral=0;map.PlacementMode=false;map.Invalidate();status.Text="도시 배치를 취소했습니다.";return true;}return base.ProcessCmdKey(ref msg,keyData);}
 void OpenDialog(){using(var d=new OpenFileDialog{Title=Lang.T("작업 시나리오 열기"),InitialDirectory=WorkspaceDirectory(),Filter=Lang.T("작업 시나리오 (*.json)|*.json"),RestoreDirectory=true})if(d.ShowDialog(this)==DialogResult.OK)OpenProject(d.FileName);}
 // The project as a file for a preview only (a map preview, the terrain list): no save checks and no new revision, so looking
 // at a terrain never sends the author to the victory page (user 2026-11-15: the terrain tab jumped to page 1).
 string PreviewSnapshot(){StoreCity();string dir=NonInteractive?Path.Combine(Root,"creator-probes","scratch"):Path.Combine(Root,"creator-cache","snapshots");Directory.CreateDirectory(dir);string tmp=Path.Combine(dir,Guid.NewGuid().ToString("N")+".json");File.WriteAllText(tmp,SerializeProject(project),new UTF8Encoding(false));return tmp;}
 string Snapshot(){StoreCity();RequireGoalsForSave();if(string.IsNullOrWhiteSpace(title.Text))throw new Exception("시나리오 이름을 입력하세요.");project.title=title.Text;project.briefing=briefingText.Text;if(revisionPending){project.revision++;revisionPending=false;}string dir=NonInteractive?Path.Combine(Root,"creator-probes","scratch"):Path.Combine(Root,"creator-cache","snapshots");Directory.CreateDirectory(dir);string tmp=Path.Combine(dir,Guid.NewGuid().ToString("N")+".json");File.WriteAllText(tmp,SerializeProject(project),new UTF8Encoding(false));try{Check(tmp,"");return tmp;}catch{File.Delete(tmp);throw;}}
 void SaveDialog(){RequireGoalsForSave();if(string.IsNullOrEmpty(currentProjectPath))SaveAsDialog();else Save(currentProjectPath);}
 void Save(string path){string full=Path.GetFullPath(path);string defaults=Path.GetFullPath(Path.Combine(Root,"scenarios"))+Path.DirectorySeparatorChar;if(full.StartsWith(defaults,StringComparison.OrdinalIgnoreCase))throw new Exception("기본 예제는 보존합니다. 다른 폴더에 저장하세요.");string tmp=Snapshot(),pending=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.Copy(tmp,pending,false);if(File.Exists(path))File.Replace(pending,path,path+"."+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")+".bak");else File.Move(pending,path);PruneBackups(path);dirty=false;currentProjectPath=full;status.Text="저장했습니다: "+full;if(!NonInteractive)RememberProject(full);}finally{File.Delete(tmp);if(File.Exists(pending))File.Delete(pending);}}
 void ExportDialog(){RequireGoalsForSave();ShowShareHelp();using(var d=new SaveFileDialog{Title=Lang.T("공유 시나리오 ZIP 저장"),InitialDirectory=WorkspaceDirectory(),Filter=Lang.T("공유 시나리오 (*.zip)|*.zip"),DefaultExt="zip",AddExtension=true,RestoreDirectory=true,FileName=ProjectFileName(".zip"),OverwritePrompt=true})if(d.ShowDialog(this)==DialogResult.OK){string tmp=Snapshot(),pending=d.FileName+"."+Guid.NewGuid().ToString("N")+".tmp";try{Check(tmp,"--export "+Quote(pending));if(File.Exists(d.FileName))File.Replace(pending,d.FileName,d.FileName+"."+DateTime.Now.ToString("yyyyMMddHHmmssfff")+".bak");else File.Move(pending,d.FileName);PruneBackups(d.FileName);status.Text="공유 ZIP을 만들었습니다. 받은 사람은 작업 목록에서 가져올 수 있습니다.";}finally{File.Delete(tmp);if(File.Exists(pending))File.Delete(pending);}}}
 void Launch(){ValidateGame(true);}
 async void ValidateGame(bool launch){string path=null;bool keep=false;try{path=Snapshot();if(launch)Check(path,"--runtime");Enabled=false;UseWaitCursor=true;status.Text="실제 게임 엔진으로 도시 지형과 이동 경로를 검사하고 있습니다…";string result=await Task.Run(()=>RunPython("creator_terrain.py","--validate "+Quote(path)));var check=Json.Deserialize<TerrainCheck>(result);if(!check.valid)throw new Exception(check.errors==null?"지형을 적용할 수 없습니다. 출입구와 수로 연결을 확인하세요.":string.Join("\n",check.errors));ForgetSeaLimits();status.Text="게임 적용 검사 완료: 도시 지형과 육상·수로 연결을 확인했습니다.";if(checkPage!=null){tabs.SelectedTab=checkPage;RefreshChecks();}if(launch){Process.Start(new ProcessStartInfo(Path.Combine(Root,"Augustus.exe"),"--project "+Quote(path)){UseShellExecute=false,WorkingDirectory=Root});keep=true;}}catch(Exception e){LangBox.Show(this,e.Message,"게임 적용 검사",MessageBoxButtons.OK,MessageBoxIcon.Warning);status.Text="게임 적용 검사를 통과하지 못했습니다. 수정 내용을 확인하세요.";}finally{Enabled=true;UseWaitCursor=false;if(path!=null&&!keep)File.Delete(path);}}

 IEnumerable<Control> AllControls(Control c){yield return c;foreach(Control child in c.Controls)foreach(var descendant in AllControls(child))yield return descendant;}
 void PrepareOffscreen(Control c){IntPtr unused=c.Handle;c.PerformLayout();foreach(Control child in c.Controls)PrepareOffscreen(child);c.PerformLayout();}
 void PaintOffscreen(Control c,Graphics g,Point origin){if(c==construction&&!construction.Enabled)return;if((c==cultureLabel||c==recipeCulture)&&goalRecipe.SelectedIndex!=1)return;if(c.Width<=0||c.Height<=0)return;var state=g.Save();g.SetClip(new Rectangle(origin,c.Size),System.Drawing.Drawing2D.CombineMode.Intersect);using(var image=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(image,new Rectangle(0,0,c.Width,c.Height));g.DrawImageUnscaled(image,origin);}var combo=c as ComboBox;if(combo!=null){var textBounds=new Rectangle(origin.X+5,origin.Y+2,Math.Max(1,c.Width-25),Math.Max(1,c.Height-4));TextRenderer.DrawText(g,Lang.T(combo.Text),combo.Font,textBounds,combo.Enabled?Dark:SystemColors.GrayText,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine);}if(c is DataGridView || c is ComboBox){g.Restore(state);return;}for(int i=c.Controls.Count-1;i>=0;i--){Control child=c.Controls[i];if(child is TabPage && ((TabControl)c).SelectedTab!=child)continue;PaintOffscreen(child,g,new Point(origin.X+child.Left,origin.Y+child.Top));}g.Restore(state);}
 void RenderEditor(string dir,int tab){tabs.SelectedIndex=tab;PrepareOffscreen(this);using(var ui=new Bitmap(ClientSize.Width,ClientSize.Height))using(var g=Graphics.FromImage(ui)){PaintOffscreen(Controls[0],g,Point.Empty);ui.Save(Path.Combine(dir,"editor-tab-"+tab+".png"));}}
 int RenderProbe(){string dir=Path.Combine(Root,"creator-probes","layout-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);foreach(int tab in new[]{0,1})RenderEditor(dir,tab);File.WriteAllText(Path.Combine(Root,"creator-render-latest.txt"),dir);dirty=false;return 0;}
 int Probe(){
  string dir=Path.Combine(Root,"creator-probes",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);objectiveMode.SelectedIndex=0;/* a new scenario has no goal yet; saving needs one (free build) */string first=Snapshot();var data=Json.Deserialize<Scenario>(File.ReadAllText(first));if(data.schema!=4||data.slots.Length!=4||data.empire.cities.Length!=39||data.empire.cities.Select(c=>c.name_id).Distinct().Count()!=39)throw new Exception("Merged default failed");if(data.empire.cities.Count(c=>c.enabled)!=4||catalogPlayable.Count!=23||!catalogPlayable.IsSubsetOf(map.PlayableCities))   /* green = the game's maps (23) and this PC's map shelf */throw new Exception("Merged color/enable defaults failed");
  foreach(var size in new[]{new Size(600,560),new Size(790,650),new Size(1200,800)})foreach(var c in data.empire.cities){var at=map.Position(c.x,c.y,size);var full=map.Project;map.Project=new Scenario{empire=new Empire{cities=new[]{c}}};if(map.Hit(at,size)!=c.name_id)throw new Exception("Map hit mismatch");map.Project=full;var back=map.World(at,size);if(Math.Abs(back.X-c.x)>1||Math.Abs(back.Y-c.y)>1)throw new Exception("World transform mismatch");}
  int originalName=project.slots[0].name_id;int green=merged.cities.First(c=>HasTerrain(c.name_id)&&!project.slots.Any(p=>p.name_id==c.name_id)).name_id;AssignCity(0,green);if(project.slots[0].name_id!=green||Array.Find(presets.terrain,t=>t.id==project.slots[0].campaign_scenario).name_id!=green)throw new Exception("Playable assignment mismatch");int brown=merged.cities.First(c=>!HasTerrain(c.name_id)).name_id;bool rejected=false;try{AssignCity(0,brown);}catch{rejected=true;}if(!rejected)throw new Exception("Neutral-only city became player");AssignCity(0,originalName);var missing=presets.terrain.Where(p=>p.name_id==green).ToArray();var availability=missing.Select(p=>p.available).ToArray();try{foreach(var item in missing)item.available=false;if(!HasTerrain(green)||LocalAvailableTerrain(green))throw new Exception("Capability and local availability conflated");bool blocked=false;try{AssignCity(0,green);}catch{blocked=true;}if(!blocked||project.slots[0].name_id!=originalName||!Array.Find(project.empire.cities,c=>c.name_id==originalName).enabled)throw new Exception("Unavailable terrain assignment was not atomic");}finally{for(int i=0;i<missing.Length;i++)missing[i].available=availability[i];}
  slotPicker.SelectedIndex=0;category="";RefreshBuildings();ProbeBuildingTiles();int building=((BuildingChoice)buildings.Items[0]).id;buildings.SetItemChecked(0,false);if(project.slots[0].allowed_buildings.Contains(building)||!project.slots[1].allowed_buildings.Contains(building))throw new Exception("Per-city building isolation failed");
  int npc=merged.cities.First(c=>c.trade_presets.Any(t=>t.id!="none")&&!project.slots.Any(p=>p.name_id==c.name_id)).name_id;SelectCity(npc);tradePresetPicker.SelectedIndex=tradePresetPicker.Items.Cast<TradePreset>().ToList().FindIndex(p=>p.id!="none"&&p.id!="custom");ApplyTradePreset();var chosen=Array.Find(project.empire.cities,c=>c.name_id==npc);if(chosen.sells.Count+chosen.buys.Count==0)throw new Exception("Trade preset not applied");cityEnabled.Checked=true;cityEnabled.Checked=false;if(chosen.sells.Count+chosen.buys.Count==0)throw new Exception("Disabling city lost trade settings");tradePresetPicker.SelectedIndex=tradePresetPicker.Items.Cast<TradePreset>().ToList().FindIndex(p=>p.id=="none");ApplyTradePreset();if(chosen.sells.Count+chosen.buys.Count!=0||tradeSummary.Text!="교역 품목: 없음")throw new Exception("No-trade preset failed");
  SelectCity(project.slots[0].name_id);objectiveMode.SelectedIndex=1;totalPopulation.Value=1200;objectiveGrid.Rows[0].Cells[2].Value=30;string goals=Snapshot();File.Copy(goals,Path.Combine(dir,"scenario-objectives.json"));var goalData=Json.Deserialize<Scenario>(File.ReadAllText(goals));if(Convert.ToString(goalData.rules["mode"])!="cooperative")throw new Exception("Goals not persisted");objectiveMode.SelectedIndex=0;string free=Snapshot();if(File.ReadAllText(free).Contains("objectives"))throw new Exception("Free build retained goals");
  var four=Json.Deserialize<Scenario>(SerializeProject(project));if(project.slots.Length!=4)throw new Exception("Expected four slots");while(project.slots.Length<8)AddPlayer();bool limit=false;try{AddPlayer();}catch{limit=true;}if(!limit||project.slots.Length!=8)throw new Exception("Eight city authoring limit failed");Adopt(four);

  var legacy=Json.Deserialize<Scenario>(SerializeProject(four));legacy.schema=3;legacy.slots[0].campaign_scenario=19;legacy.slots[0].terrain_edits=new[]{new TerrainEdit{x=20,y=20,kind="rock"}};Upgrade(legacy);if(legacy.slots[0].campaign_scenario!=19||legacy.slots[0].terrain_edits.Length!=1)throw new Exception("Legacy terrain assignment lost");Adopt(legacy);if(!terrain.Text.StartsWith("기존 배정"))throw new Exception("Legacy mismatch label missing");Adopt(four);
  string changed=Snapshot();File.Copy(changed,Path.Combine(dir,"scenario.json"));/* export needs the engine check first, as in the editor (4 검증·내보내기 -> 게임 적용 검사) */var engineCheck=Json.Deserialize<TerrainCheck>(RunPython("creator_terrain.py","--validate "+Quote(changed)));if(engineCheck==null||!engineCheck.valid)throw new Exception("Engine check failed: "+(engineCheck==null||engineCheck.errors==null?"":string.Join(" / ",engineCheck.errors)));Check(changed,"--export "+Quote(Path.Combine(dir,"scenario.zip")));using(var bitmap=new Bitmap(1100,650))using(var g=Graphics.FromImage(bitmap)){map.Draw(g,bitmap.Size);bitmap.Save(Path.Combine(dir,"empire-preview.png"));}SelectCity(npc);RenderEditor(dir,0);File.Copy(Path.Combine(dir,"editor-tab-0.png"),Path.Combine(dir,"editor-neutral.png"));SelectCity(green);RenderEditor(dir,0);File.Copy(Path.Combine(dir,"editor-tab-0.png"),Path.Combine(dir,"editor-unassigned.png"));SelectCity(project.slots[0].name_id);foreach(int tab in new[]{0,1,2})RenderEditor(dir,tab);objectiveMode.SelectedIndex=1;totalPopulation.Value=1200;objectiveGrid.Rows[0].Cells[2].Value=30;RenderEditor(dir,3);objectiveMode.SelectedIndex=0;var choices=CityTerrains(project.slots[0].name_id);using(var picker=new CreatorPresetPicker(choices,project.slots[0].campaign_scenario,LoadTerrain,true)){PrepareOffscreen(picker);using(var image=new Bitmap(picker.ClientSize.Width,picker.ClientSize.Height))using(var g=Graphics.FromImage(image)){PaintOffscreen(picker.Controls[0],g,Point.Empty);image.Save(Path.Combine(dir,"terrain-preset-picker.png"));}}
  var states=new List<object>();foreach(var combo in AllControls(this).OfType<ComboBox>()){if(combo.SelectedIndex<0||combo.SelectedItem==null||string.IsNullOrWhiteSpace(combo.Text))throw new Exception("Dropdown selection missing: "+(combo.AccessibleName??combo.Name)+" / items "+combo.Items.Count+(combo.Items.Count>0?" / first "+combo.Items[0]:"")+" / near "+(combo.Parent==null?"":string.Join(" | ",combo.Parent.Controls.Cast<Control>().Select(c=>c.GetType().Name+":"+c.Text).Take(8))));states.Add(new{index=combo.SelectedIndex,text=combo.Text});}File.WriteAllText(Path.Combine(dir,"dropdown-state.json"),Json.Serialize(states));File.WriteAllText(Path.Combine(dir,"result.json"),Json.Serialize(new{passed=true,schema=4,merged_cities=39,terrain_city_names=map.PlayableCities.Count,authoring_slots=4,fifth_player_rejected=true,per_city_buildings=true,trade_source_presets=true,empty_trade_preset=true,cooperative_objectives=true,legacy_terrain_preserved=true,gui_automated=false}));File.WriteAllText(Path.Combine(Root,"creator-probe-latest.txt"),dir);dirty=false;return 0;
 }
 static int LargeJsonProbe(){var sample=new Scenario{schema=3,id="large-serialization-check",title="8개 도시 지형 직렬화 검사",revision=1,rules=new Dictionary<string,object>{{"mode","free-build"},{"player_transport","land"},{"starting_funds",10000}},empire=new Empire{template=25,cities=new City[0]},slots=new Slot[8]};for(int slot=0;slot<8;slot++){var cells=new TerrainEdit[25600];for(int n=0;n<cells.Length;n++)cells[n]=new TerrainEdit{x=n%160,y=n/160,kind="land"};sample.slots[slot]=new Slot{id="player"+(slot+1),name_id=slot+1,campaign_scenario=2,allowed_buildings=new int[0],terrain_edits=cells};}string json=Json.Serialize(sample);int bytes=Encoding.UTF8.GetByteCount(json);if(bytes<=2097152||bytes>16777216)throw new Exception("Large project size boundary failed");var decoded=Json.Deserialize<Scenario>(json);if(decoded.slots.Length!=8||decoded.slots.Any(s=>s.terrain_edits.Length!=25600)||decoded.slots[7].terrain_edits[25599].y!=159)throw new Exception("Large project roundtrip failed");string dir=Path.Combine(Root,"creator-probes","large-json-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"result.json"),Json.Serialize(new{passed=true,slots=8,tiles_per_slot=25600,utf8_bytes=bytes,limit_bytes=16777216,synthetic_serialization_only=true}));File.WriteAllText(Path.Combine(Root,"creator-large-json-latest.txt"),dir);return 0;}
 static int GovernanceProbe(){
  var data=new Scenario{schema=4,slots=new[]{new Slot{id="player1"},new Slot{id="player2",governance=new Governance{rank=5,salary_rank=-1,savings=1234,favor=73,policy="fixed"}}},empire=new Empire{cities=new City[0]}};
  string json=SerializeProject(data);var result=Json.Deserialize<Scenario>(json);
  if(result.slots[0].governance!=null || result.slots[1].governance.rank!=5 || result.slots[1].governance.salary_rank!=-1 || result.slots[1].governance.favor!=73)throw new Exception("Governance roundtrip failed");
  var records=(System.Collections.IEnumerable)Json.Deserialize<Dictionary<string,object>>(json)["slots"];int index=0;foreach(Dictionary<string,object> r in records){if(index++==0 && r.ContainsKey("governance"))throw new Exception("Legacy field changed");}
  File.WriteAllText(Path.Combine(Root,"governance-ui-probe.json"),"{\"passed\":true,\"form_created\":false,\"legacy_preserved\":true}");return 0;
 }
 static int StartingSetupProbe(){
  var d=new Scenario{schema=4,slots=new[]{new Slot{id="player1"},new Slot{id="player2",starting_setup="defense-town"}},empire=new Empire{cities=new City[0]}};
