  if(result.slots[0].starting_setup!=null||result.slots[1].starting_setup!="defense-town")throw new Exception("Starting setup roundtrip failed");
  var records=(System.Collections.IEnumerable)Json.Deserialize<Dictionary<string,object>>(json)["slots"];int i=0;foreach(Dictionary<string,object> r in records)if(i++==0&&r.ContainsKey("starting_setup"))throw new Exception("Legacy setup changed");
  File.WriteAllText(Path.Combine(Root,"starting-setup-probe.json"),"{\"passed\":true,\"form_created\":false}");return 0;
 }
 [STAThread] static int Main(string[] args){try{NonInteractive=args.Length>0;Lang.Init(Root,NonInteractive);if(args.Length==2 && args[0]=="--runtime-check"){Check(args[1],"--runtime");return 0;}if(args.Length==1 && args[0]=="--throne-probe")return ThroneProbe();if(args.Length==1 && args[0]=="--briefing-probe")return BriefingProbe();if(args.Length==1 && args[0]=="--starting-setup-probe")return StartingSetupProbe();if(args.Length==1 && args[0]=="--invasions-probe")return InvasionsProbe();if(args.Length==1 && args[0]=="--city-events-probe")return CityEventsProbe();if(args.Length==1 && args[0]=="--delivery-policy-probe")return DeliveryPolicyProbe();if(args.Length==1 && args[0]=="--governance-policy-probe")return GovernanceProbe();if(args.Length==1 && args[0]=="--goal-policy-probe")return GoalPolicyProbe();if(args.Length==1 && args[0]=="--startup-data-probe")return StartupDataProbe();Application.EnableVisualStyles();if(args.Length==1 && args[0]=="--workflow-probe"){using(var form=new ScenarioCreator())return form.MapWorkflowProbe();}if(args.Length==1 && args[0]=="--large-json-probe")return LargeJsonProbe();if(args.Length==1 && args[0]=="--native-bridge-probe"){using(var form=new ScenarioCreator())return form.NativeBridgeProbe();}if(args.Length==1 && args[0]=="--render-only"){using(var form=new ScenarioCreator())return form.RenderProbe();}if(args.Length==1 && args[0]=="--workflow-layout-probe"){using(var form=new ScenarioCreator())return form.LayoutProbe();}if(args.Length==1 && (args[0]=="--self-test" || args[0]=="--map-probe" || args[0]=="--data-probe")){using(var form=new ScenarioCreator())return form.Probe();}return RunStartup();}catch(OperationCanceledException){return 0;}catch(Exception e){File.WriteAllText(Path.Combine(Root,"creator-error.log"),e.ToString(),Encoding.UTF8);if(args.Length==0)LangBox.Show(e.Message,"제작기 오류");return 1;}}
